import io.github.wurtzitane.avogadro.api.*;

final class MoleculeTransactionRecipe {
    // Common initialization or a server action. Prepare immutable data before submitting the commit.
    static RegistrationJob install() {
        var water = AvogadroApi.builder("example:water")
            .smiles("[H]O[H]")
            .itemTags("example:water_items")
            .fluidTags("example:water_fluids")
            .build();
        var job = AvogadroApi.owner("example_recipes")
            .submit(true, batch -> batch
                .register(water)
                .remove("example:old_water")
                .itemTag("example:water_items", false, "minecraft:water_bucket")
                .fluidTag("example:water_fluids", false, "water"));
        job.onComplete(outcome -> {
            if (outcome.state() == RegistrationJob.State.SUCCEEDED)
            System.out.println("Published revision " + outcome.view()
                .revision());
            else if (outcome.failure() != null)
            System.err.println("Previous definitions retained: " + outcome.failure());
        });
        return job; // Retain the handle. Callbacks use the completing thread, not an implied UI thread.
    }
    // Common teardown. Cleanup is another conditional publication and can fail if other definitions depend on it.
    static void unload(RegistrationJob job) {
        job.release()
            .whenComplete((view, failure) -> {
                if (failure != null) System.err.println("Cleanup rejected; retry after resolving dependencies: " + failure);
            });
    }
    // job.cancel() prevents pending work only. False means the atomic application already started or finished.
}

