    .smiles("[H]O[H]")
    .itemTag("example:water_items")
    .fluidTag("example:water_fluids");
val draft = Molecules.transaction("example_recipes")
    .replaceAll()
    .register(water)
    .remove("example:old_water")
    .itemTag("example:water_items", false, ["minecraft:water_bucket"])
    .fluidTag("example:water_fluids", false, ["water"]);
val owned = draft.commit();
owned.onComplete(function(outcome) {
    if (outcome.state == "succeeded") print("Published revision " + outcome.revision);
    else print("Previous definitions retained: " + outcome.failure);
});

// A later server/controller action can prevent queued publication, but cannot cancel an applying commit.
function cancelPending(job as RegistrationJob) as bool {
    return job.cancel();
}
