import io.github.wurtzitane.avogadro.api.*;

final class PreparationRecipe implements AutoCloseable {
    private final PreparationScope scope = new PreparationScope();
    private PreparationScope.Job<MoleculeSpec> pending;
    private MoleculeSpec prepared;

    // Common CPU request. Supply a delivery executor for the actual owning client/server thread.
    void prepare(Executor delivery) {
        pending = scope.molecule("editor",
            "example:water",
            builder -> builder.smiles("[H]O[H]"));
        pending.deliver(delivery, (value, failure) -> {
            if (failure != null) System.err.println("Preparation failed: " + failure);
            else prepared = value; // Still unregistered. Deliberately publish it through your owner's transaction.
        });
    }
    // The same scope also owns cancellable network realizations, with separate replaceable result slots.
    void realize(PolymerNetworkDefinition recipe,
        NetworkPreviewRequest request,
        Executor delivery) {
            scope.network("network", recipe, request)
                .deliver(delivery, (preview, failure) -> {
                    if (failure != null) System.err.println(failure);
                    else System.out.println(preview.formula());
                });
        }
    // Owner action: cancellation prevents future delivery and interrupts pending CPU work.
    boolean cancel() {
        return pending != null && pending.cancel();
    }
    // Teardown: suppresses results even if their delivery was already queued on another executor.
    @Override public void close() {
        scope.close();
    }
    // Client setup may supply task -> Minecraft.getMinecraft().addScheduledTask(task).
    // Server setup supplies its server scheduler. The scope never selects either thread implicitly.
}

